={{ $('Edit Fields | Preparar datos para memoria').isExecuted
  ? $('Edit Fields | Preparar datos para memoria').first().json.chatInput
  : $('Chat - Entrada de consultas').first().json.chatInput }}

={{ $json.worker === 'fallback'
  ? 'No aplica: no se invocó un Worker'
  : JSON.stringify({
      consulta: $('Edit Fields | Preparar datos para memoria').isExecuted
        ? $('Edit Fields | Preparar datos para memoria').first().json.chatInput
        : $('Chat - Entrada de consultas').first().json.chatInput,
      tipo_usuario: $json.worker === 'compradores'
        ? 'comprador'
        : 'productor',
      categoria: JSON.parse(
        $('Manager - Orquestador').first().json.output
      ).categoria
    })
}}

value.Session_ID:
={{ $('Edit Fields | Preparar datos para memoria').isExecuted
  ? $('Edit Fields | Preparar datos para memoria').first().json.sessionId
  : $('Chat - Entrada de consultas').first().json.sessionId }}

value.Historial_Reciente:
={{ 'Usuario: ' + (
  $('Edit Fields | Preparar datos para memoria').isExecuted
    ? $('Edit Fields | Preparar datos para memoria').first().json.chatInput
    : $('Chat - Entrada de consultas').first().json.chatInput
) }}

={{ [
  ($json.fields.Historial_Reciente ?? '').trim(),
  'Usuario: ' + (
    $('Edit Fields | Preparar datos para memoria').isExecuted
      ? $('Edit Fields | Preparar datos para memoria').first().json.chatInput
      : $('Chat - Entrada de consultas').first().json.chatInput
  )
].filter(Boolean).join('\n') }}

